//! What to index: Git-visible source files, their packages and module paths, and content hashes.
//!
//! Files come from `git ls-files` (tracked plus untracked-but-not-ignored), so build outputs,
//! `node_modules`, caches and anything else `.gitignore` excludes never enter the index. Generated
//! files (an `@generated` / `DO NOT EDIT` header) and very large files are skipped as well.

use anyhow::{Context, Result, bail};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::UNIX_EPOCH;

/// Files above this size are not source anyone navigates by symbol.
pub const MAX_FILE_BYTES: u64 = 1 << 20;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Lang {
    Rust,
    Ts,
    Tsx,
}

impl Lang {
    pub fn from_path(path: &str) -> Option<Lang> {
        let ext = path.rsplit_once('.').map(|(_, e)| e)?;
        match ext {
            "rs" => Some(Lang::Rust),
            "ts" | "mts" | "cts" | "js" | "mjs" | "cjs" => Some(Lang::Ts),
            "tsx" | "jsx" => Some(Lang::Tsx),
            _ => None,
        }
    }

    pub fn as_str(self) -> &'static str {
        match self {
            Lang::Rust => "rust",
            Lang::Ts | Lang::Tsx => "ts",
        }
    }
}

/// Path segments that never hold hand-written source, even when Git tracks them.
const EXCLUDED_DIRS: &[&str] = &["target", "node_modules", "dist", "build", ".codegraph", "vendor", "coverage"];

#[derive(Debug, Clone)]
pub struct Package {
    pub name: String,
    pub ident: String,
    pub lang: &'static str,
    pub manifest: String,
    pub root: String,
    pub deps: Vec<(String, &'static str)>,
}

#[derive(Debug, Clone)]
pub struct SourceFile {
    pub path: String,
    pub lang: Lang,
    pub size: u64,
    pub mtime_ns: i64,
}

pub fn repo_root(start: &Path) -> Result<PathBuf> {
    let out = Command::new("git")
        .arg("-C")
        .arg(start)
        .args(["rev-parse", "--show-toplevel"])
        .output()
        .context("running git (codegraph needs a Git work tree)")?;
    if !out.status.success() {
        bail!("{} is not inside a Git work tree", start.display());
    }
    Ok(PathBuf::from(String::from_utf8_lossy(&out.stdout).trim()))
}

/// `HEAD` commit, or None in a repository without commits.
pub fn head_rev(root: &Path) -> Option<String> {
    let out = Command::new("git").arg("-C").arg(root).args(["rev-parse", "HEAD"]).output().ok()?;
    out.status.success().then(|| String::from_utf8_lossy(&out.stdout).trim().to_string())
}

/// Every Git-visible path (tracked and untracked-not-ignored) that still exists on disk.
pub fn git_files(root: &Path) -> Result<Vec<String>> {
    let out = Command::new("git")
        .arg("-C")
        .arg(root)
        .args(["ls-files", "-z", "--cached", "--others", "--exclude-standard"])
        .output()
        .context("running git ls-files")?;
    if !out.status.success() {
        bail!("git ls-files failed: {}", String::from_utf8_lossy(&out.stderr).trim());
    }
    let mut v: Vec<String> =
        out.stdout.split(|b| *b == 0).filter(|s| !s.is_empty()).filter_map(|s| std::str::from_utf8(s).ok().map(str::to_string)).collect();
    v.sort();
    v.dedup();
    Ok(v)
}

fn excluded(path: &str) -> bool {
    path.split('/').any(|seg| EXCLUDED_DIRS.contains(&seg))
}

pub fn stat(root: &Path, path: &str) -> Option<(u64, i64)> {
    let md = std::fs::metadata(root.join(path)).ok()?;
    if !md.is_file() {
        return None;
    }
    let mtime =
        md.modified().ok().and_then(|t| t.duration_since(UNIX_EPOCH).ok()).map(|d| i64::try_from(d.as_nanos()).unwrap_or(i64::MAX)).unwrap_or(0);
    Some((md.len(), mtime))
}

/// Source files to index, from the Git-visible paths.
pub fn source_files(root: &Path, all: &[String]) -> Vec<SourceFile> {
    all.iter()
        .filter(|p| !excluded(p))
        .filter_map(|p| {
            let lang = Lang::from_path(p)?;
            if p.ends_with(".d.ts") {
                return None;
            }
            let (size, mtime_ns) = stat(root, p)?;
            (size <= MAX_FILE_BYTES).then(|| SourceFile { path: p.clone(), lang, size, mtime_ns })
        })
        .collect()
}

/// True for files a generator wrote (checked on the first bytes only).
pub fn is_generated(text: &str) -> bool {
    let head: String = text.chars().take(600).collect();
    head.contains("@generated") || head.contains("DO NOT EDIT") || head.contains("auto-generated") || head.contains("autogenerated by")
}

pub fn hash(bytes: &[u8]) -> String {
    blake3::hash(bytes).to_hex().to_string()
}

/// Cargo and npm packages from every Git-visible manifest outside excluded directories.
pub fn packages(root: &Path, all: &[String]) -> Vec<Package> {
    let mut out = Vec::new();
    for p in all.iter().filter(|p| !excluded(p)) {
        let dir = p.rsplit_once('/').map(|(d, _)| d.to_string()).unwrap_or_default();
        if p == "Cargo.toml" || p.ends_with("/Cargo.toml") {
            if let Some(pkg) = cargo_package(root, p, &dir) {
                out.push(pkg);
            }
        } else if (p == "package.json" || p.ends_with("/package.json"))
            && let Some(pkg) = npm_package(root, p, &dir)
        {
            out.push(pkg);
        }
    }
    // Names must be unique in the index; keep the first (shortest path) on a clash.
    out.sort_by(|a, b| a.manifest.len().cmp(&b.manifest.len()).then(a.manifest.cmp(&b.manifest)));
    let mut seen = std::collections::HashSet::new();
    out.retain(|p| seen.insert(p.name.clone()));
    out
}

fn cargo_package(root: &Path, manifest: &str, dir: &str) -> Option<Package> {
    let text = std::fs::read_to_string(root.join(manifest)).ok()?;
    let doc: toml::Table = text.parse().ok()?;
    let name = doc.get("package")?.get("name")?.as_str()?.to_string();
    let mut deps = Vec::new();
    for (section, kind) in [("dependencies", "normal"), ("dev-dependencies", "dev"), ("build-dependencies", "build")] {
        if let Some(t) = doc.get(section).and_then(|v| v.as_table()) {
            for (k, v) in t {
                // `alias = { package = "real-name" }` depends on real-name.
                let real = v.get("package").and_then(|p| p.as_str()).unwrap_or(k);
                deps.push((real.to_string(), kind));
            }
        }
    }
    // A [lib] name overrides the crate identifier code uses.
    let ident = doc.get("lib").and_then(|l| l.get("name")).and_then(|n| n.as_str()).map(str::to_string).unwrap_or_else(|| name.replace('-', "_"));
    Some(Package { ident, name, lang: "rust", manifest: manifest.to_string(), root: dir.to_string(), deps })
}

fn npm_package(root: &Path, manifest: &str, dir: &str) -> Option<Package> {
    let text = std::fs::read_to_string(root.join(manifest)).ok()?;
    let v: serde_json::Value = serde_json::from_str(&text).ok()?;
    let name = v.get("name")?.as_str()?.to_string();
    let mut deps = Vec::new();
    for (section, kind) in [("dependencies", "normal"), ("devDependencies", "dev"), ("peerDependencies", "normal")] {
        if let Some(o) = v.get(section).and_then(|d| d.as_object()) {
            deps.extend(o.keys().map(|k| (k.clone(), kind)));
        }
    }
    Some(Package { ident: name.clone(), name, lang: "ts", manifest: manifest.to_string(), root: dir.to_string(), deps })
}

/// A fingerprint of package names and roots: when it changes, module paths may change everywhere.
pub fn packages_fingerprint(pkgs: &[Package]) -> String {
    let mut s = String::new();
    for p in pkgs {
        s.push_str(&format!("{}|{}|{}|{}\n", p.name, p.ident, p.root, p.lang));
    }
    hash(s.as_bytes())
}

/// The package that owns `path`: the deepest package root of the same language above it.
pub fn owning_package<'a>(pkgs: &'a [Package], path: &str, lang: Lang) -> Option<&'a Package> {
    pkgs.iter()
        .filter(|p| p.lang == lang.as_str())
        .filter(|p| p.root.is_empty() || path.starts_with(&format!("{}/", p.root)))
        .max_by_key(|p| p.root.len())
}

/// Module path for a file (syntax-derived; `#[path]` attributes are not followed).
pub fn module_path(pkg: Option<&Package>, path: &str, lang: Lang) -> String {
    let stem = path.rsplit_once('.').map(|(s, _)| s).unwrap_or(path);
    match lang {
        Lang::Ts | Lang::Tsx => stem.to_string(),
        Lang::Rust => {
            let Some(pkg) = pkg else { return stem.replace('/', "::") };
            let rel = if pkg.root.is_empty() { stem } else { stem.strip_prefix(&format!("{}/", pkg.root)).unwrap_or(stem) };
            let mut segs: Vec<&str> = rel.split('/').collect();
            match segs.first() {
                Some(&"src") => {
                    segs.remove(0);
                }
                Some(&("tests" | "benches" | "examples")) => {}
                _ => {}
            }
            if matches!(segs.last(), Some(&("mod" | "lib" | "main"))) {
                segs.pop();
            }
            let mut m = pkg.ident.clone();
            for s in segs {
                m.push_str("::");
                m.push_str(s);
            }
            m
        }
    }
}

pub fn is_test_path(path: &str) -> bool {
    let file = path.rsplit('/').next().unwrap_or(path);
    path.starts_with("tests/")
        || path.contains("/tests/")
        || file.ends_with("_tests.rs")
        || file.ends_with("_test.rs")
        || file == "tests.rs"
        || file.contains(".test.")
        || file.contains(".spec.")
}

/// Current on-disk state of the indexed files, for freshness checks: path -> (size, mtime).
pub fn disk_state(root: &Path) -> Result<BTreeMap<String, (u64, i64)>> {
    let all = git_files(root)?;
    Ok(source_files(root, &all).into_iter().map(|f| (f.path, (f.size, f.mtime_ns))).collect())
}
